Ecm_Vtacho_Evt ecm_vtacho_delay( void )
{
	if( ecm_vtacho_vars.time ++  == ecm_vtacho_vars.cranking_time )
	{
		ecm_vtacho_vars.time = 0 ; 
		
		ecm_vtacho_vars.state = ecm_vtacho_check ;
		
		voltage_set_sampling_period(5) ; //50ms for sampling period
				
		return ECM_VTACHO_EVT_CRANK_RELEASE ;
	}

	return ECM_VTACHO_EVT_NULL ; 
}

